#!/usr/bin/env node
// Refresh the static model-benchmark snapshot (src/benchmarks.json) from
// Artificial Analysis. Run manually when you want fresh numbers — opencode does
// NOT expose benchmarks, and AA data is the only API source we found.
//
// Usage:
//   AA_API_KEY=aa_... node scripts/refresh-benchmarks.mjs          # fetch live
//   node scripts/refresh-benchmarks.mjs --from /tmp/aa.json        # from raw dump
//
// Covers ALL AA-scored models (every creator — anthropic, openai, google,
// alibaba, zai/GLM, kimi, deepseek, …), keyed by AA slug. Lookup from an
// opencode `provider/model` id is done in src/benchmarks.js.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const OUT = path.resolve(__dirname, "..", "src", "benchmarks.json");
const ENDPOINT = "https://artificialanalysis.ai/api/v2/data/llms/models";

const num = (v) => (typeof v === "number" ? v : null);

function transform(rawData) {
  /** @type {Record<string, any>} */
  const models = {};
  let scored = 0;
  for (const x of rawData) {
    const ev = x.evaluations || {};
    const intelligence = num(ev.artificial_analysis_intelligence_index);
    if (intelligence == null) continue; // keep only AA-scored models
    scored++;
    const pr = x.pricing || {};
    models[x.slug] = {
      name: x.name,
      creator: (x.model_creator || {}).slug ?? null,
      release_date: x.release_date ?? null,
      // headline indices
      intelligence,
      coding: num(ev.artificial_analysis_coding_index),
      math: num(ev.artificial_analysis_math_index),
      // agentic / tool-use benchmarks (no single "agentic index" in the API)
      agentic: {
        tau2: num(ev.tau2),
        tau_banking: num(ev.tau_banking),
        terminalbench_hard: num(ev.terminalbench_hard),
        terminalbench_v2_1: num(ev.terminalbench_v2_1),
        lcr: num(ev.lcr),
      },
      // the rest of the eval suite
      benchmarks: {
        gpqa: num(ev.gpqa),
        hle: num(ev.hle),
        livecodebench: num(ev.livecodebench),
        scicode: num(ev.scicode),
        mmlu_pro: num(ev.mmlu_pro),
        math_500: num(ev.math_500),
        aime: num(ev.aime),
        aime_25: num(ev.aime_25),
        ifbench: num(ev.ifbench),
      },
      // cost (AA has no "cost per task"; blended $/1M is the cost proxy)
      price_blended: num(pr.price_1m_blended_3_to_1),
      price_input: num(pr.price_1m_input_tokens),
      price_output: num(pr.price_1m_output_tokens),
      // speed
      tps: num(x.median_output_tokens_per_second),
      ttft: num(x.median_time_to_first_token_seconds),
    };
  }
  return { models, scored };
}

async function loadRaw(argv) {
  const fromIdx = argv.indexOf("--from");
  if (fromIdx !== -1) {
    const file = argv[fromIdx + 1];
    return JSON.parse(fs.readFileSync(file, "utf8"));
  }
  const key = process.env.AA_API_KEY;
  if (!key) {
    console.error(
      "No AA_API_KEY in env and no --from <file>. Set AA_API_KEY or pass a raw dump.",
    );
    process.exit(2);
  }
  const res = await fetch(ENDPOINT, { headers: { "x-api-key": key } });
  if (!res.ok) {
    console.error(`AA API ${res.status} ${res.statusText}`);
    process.exit(1);
  }
  return res.json();
}

async function main() {
  const raw = await loadRaw(process.argv.slice(2));
  const data = raw.data || raw;
  const { models, scored } = transform(data);
  const snapshot = {
    _meta: {
      source: "artificialanalysis.ai",
      endpoint: ENDPOINT,
      generated: new Date().toISOString().slice(0, 10),
      model_count: scored,
      note: "Keyed by AA slug. Map an opencode provider/model id via src/benchmarks.js. Indices ~0-100; price is $/1M blended (3:1). No native agentic index — see agentic.* benchmarks. No cost-per-task — price_blended is the proxy.",
    },
    models,
  };
  fs.writeFileSync(OUT, JSON.stringify(snapshot, null, 1) + "\n");
  console.log(`Wrote ${OUT}: ${scored} scored models.`);
}

main();

#!/usr/bin/env node
// Scaffold the per-model squad — a grunt AND a drill per model — from one list.
//
// Usage:
//   node squad-draft.mjs [--dir <agentDir>] [--no-prune] <provider/model>...
//
// Defaults to the global agent dir (~/.config/opencode/agent). Re-running syncs
// the managed set: it (re)writes grunt-<slug>.md + drill-<slug>.md for each
// listed model, and prunes previously generated grunt-/drill- (and legacy
// worker-) files carrying our marker that are no longer in the list.
// Hand-authored agents are never touched.

import fs from "node:fs";
import path from "node:path";
import os from "node:os";
import { fileURLToPath } from "node:url";

import { agentMarkdown, GENERATED_MARKER_DETECT } from "../src/workers.js";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PACKAGE_ROOT = path.resolve(__dirname, "..");
const PROMPTS = {
  grunt: path.join(PACKAGE_ROOT, "prompts", "grunt.md"),
  drill: path.join(PACKAGE_ROOT, "prompts", "drill.md"),
};
const ROLES = ["grunt", "drill"];

function parseArgs(argv) {
  const models = [];
  let dir = path.join(os.homedir(), ".config", "opencode", "agent");
  let prune = true;
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--dir") dir = argv[++i];
    else if (a === "--no-prune") prune = false;
    else if (a.startsWith("--")) {
      console.error(`Unknown flag: ${a}`);
      process.exit(2);
    } else models.push(a);
  }
  return { models, dir, prune };
}

function main() {
  const { models, dir, prune } = parseArgs(process.argv.slice(2));
  if (models.length === 0) {
    console.error(
      "No models given. Usage: squad-draft.mjs [--dir <d>] [--no-prune] <provider/model>...",
    );
    process.exit(2);
  }

  const body = Object.fromEntries(
    ROLES.map((r) => [r, fs.readFileSync(PROMPTS[r], "utf8")]),
  );
  fs.mkdirSync(dir, { recursive: true });

  const written = [];
  const wanted = new Set();
  for (const id of models) {
    for (const role of ROLES) {
      const { slug, filename, content } = agentMarkdown(role, id, body[role]);
      wanted.add(slug);
      fs.writeFileSync(path.join(dir, filename), content);
      written.push({ id, filename });
    }
  }

  // Prune our own previously-generated grunts/drills (and legacy worker-) no
  // longer requested. Only files carrying our marker prefix are touched.
  const pruned = [];
  if (prune) {
    for (const f of fs.readdirSync(dir)) {
      if (!/^(?:grunt|drill|worker)-.*\.md$/.test(f)) continue;
      if (wanted.has(f.replace(/\.md$/, ""))) continue;
      const full = path.join(dir, f);
      let txt = "";
      try {
        txt = fs.readFileSync(full, "utf8");
      } catch {
        continue;
      }
      if (txt.includes(GENERATED_MARKER_DETECT)) {
        fs.unlinkSync(full);
        pruned.push(f);
      }
    }
  }

  console.log(`Agent dir: ${dir}`);
  for (const w of written) console.log(`  wrote  ${w.filename}   (${w.id})`);
  for (const f of pruned) console.log(`  pruned ${f}`);
  console.log(
    `\n${models.length} model(s) -> ${written.length} agents (grunt + drill), ${pruned.length} pruned.`,
  );
  console.log(
    "Reload opencode (restart the TUI / start a new run) to pick up the new agents.",
  );
}

main();
